interface ShimPluginDescriptor {
    pluginName: string;
    methods: string[];
}
interface ShimCallResult {
    data?: unknown;
    error?: {
        message: string;
        code?: string;
    };
}
interface ShimTransport {
    getBootstrap(): {
        platformName: string;
        plugins: ShimPluginDescriptor[];
    };
    invoke(pluginName: string, methodName: string, args: unknown[]): Promise<ShimCallResult>;
    addListener(pluginName: string, eventName: string, callback: (data: unknown) => void): number;
    removeListener(pluginName: string, listenerId: number): Promise<void>;
    removeAllListeners(pluginName: string, eventName?: string): Promise<void>;
}
